<script setup lang="ts">
import { Head, router, useForm } from '@inertiajs/vue3';
import EmptyState from '../../Components/Feedback/EmptyState.vue';
import Pagination from '../../Components/Navigation/Pagination.vue';
import AppLayout from '../../Layouts/AppLayout.vue';
interface Row { id:number; uuid:string; type:string; severity:string; code:string; title:string; message:string; delivery_status:string; delivery_error:string|null; delivery_attempts:number; channels:string[]; occurred_at:string|null; notified_at:string|null; last_delivery_at:string|null }
interface Page<T>{data:T[];links:Array<{url:string|null;label:string;active:boolean}>}
const props=defineProps<{store:{id:number;name:string};notifications:Page<Row>;filters:{status?:string;type?:string};channels:{mail:boolean;feishu:boolean}}>();
const form=useForm({status:props.filters.status??'',type:props.filters.type??''});
const submit=()=>router.get('/notifications',{status:form.status||undefined,type:form.type||undefined},{preserveState:true});
const resend=(id:number)=>router.post(`/notifications/${id}/resend`,{}, {preserveScroll:true});
const statusLabel=(value:string)=>({pending:'等待发送',sent:'发送成功',failed:'发送失败',skipped:'未启用'}[value]??value);
const statusClass=(value:string)=>({sent:'bg-emerald-50 text-emerald-700',failed:'bg-rose-50 text-rose-700',pending:'bg-blue-50 text-blue-700',skipped:'bg-slate-100 text-slate-600'}[value]??'bg-slate-100 text-slate-600');
const typeLabel=(value:string)=>({sync:'数据同步',webhook:'Webhook',connection:'连接状态'}[value]??value);
const date=(value:string|null)=>value?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—';
</script>
<template><Head title="通知中心"/><AppLayout :breadcrumbs="[{label:'工作台',href:'/dashboard'},{label:'通知中心'}]"><div class="mx-auto max-w-7xl space-y-6"><header class="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p class="text-sm font-semibold text-emerald-700">{{store.name}}</p><h1 class="mt-1 text-3xl font-semibold text-slate-950">通知中心</h1><p class="mt-2 text-sm text-slate-500">查看异常告警通过店铺邮箱和飞书机器人的发送结果。</p></div><div class="flex flex-wrap gap-2"><span class="rounded-full px-3 py-1.5 text-xs font-semibold" :class="channels.mail?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'">邮箱 {{channels.mail?'已启用':'未启用'}}</span><span class="rounded-full px-3 py-1.5 text-xs font-semibold" :class="channels.feishu?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'">飞书 {{channels.feishu?'已启用':'未启用'}}</span></div></header><form class="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-[220px_220px_auto]" @submit.prevent="submit"><select v-model="form.status" class="rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm"><option value="">全部发送状态</option><option value="pending">等待发送</option><option value="sent">发送成功</option><option value="failed">发送失败</option><option value="skipped">未启用</option></select><select v-model="form.type" class="rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm"><option value="">全部通知类型</option><option value="sync">数据同步</option><option value="webhook">Webhook</option><option value="connection">连接状态</option></select><button class="rounded-xl bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white">筛选</button></form><section v-if="notifications.data.length" class="space-y-3"><article v-for="item in notifications.data" :key="item.id" class="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-600">{{typeLabel(item.type)}}</span><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="statusClass(item.delivery_status)">{{statusLabel(item.delivery_status)}}</span><span v-for="channel in item.channels" :key="channel" class="text-xs font-semibold text-slate-400">{{channel==='mail'?'邮箱':'飞书'}}</span></div><h2 class="mt-3 font-semibold text-slate-950">{{item.title}}</h2><p class="mt-1 text-sm leading-6 text-slate-600">{{item.message}}</p><p class="mt-3 text-xs text-slate-400">{{date(item.occurred_at)}} · {{item.code}} · 已尝试 {{item.delivery_attempts}} 次</p><p v-if="item.delivery_error" class="mt-2 text-xs text-rose-600">{{item.delivery_error}}</p></div><button v-if="item.delivery_status==='failed'||item.delivery_status==='skipped'" class="shrink-0 rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 hover:border-emerald-300 hover:text-emerald-700" @click="resend(item.id)">重新发送</button></div></article></section><EmptyState v-else title="暂无通知记录" description="发生连接、同步或 Webhook 异常后，通知记录会显示在这里。" icon="status"/><Pagination :links="notifications.links"/></div></AppLayout></template>
